# All existing target container PIDs retained; host owns the transaction.
def at_path(r,path)
  path.inject(r) do |p,n|
    a=p.entities.grep(Sketchup::Group).select { |g| g.name==n }
    raise "Missing or ambiguous owned child #{n}" unless a.length==1
    a.first
  end
end
def box(p,n,x,y,z,w,d,h,m)
  raise 'Bad box dimension' unless [w,d,h].all? { |v| v>0 }
  raise "Duplicate semantic ID #{n}" if p.entities.grep(Sketchup::Group).any? { |g| g.name==n }
  g=p.entities.add_group; g.name=n
  f=g.entities.add_face([[x,y,z],[x+w,y,z],[x+w,y+d,z],[x,y+d,z]].map { |q| q.map { |v| v.mm } })
  f.reverse! if f.normal.z<0; f.pushpull(h.mm)
  g.entities.grep(Sketchup::Face).each { |q| q.material=m; q.back_material=m }
  g.entities.grep(Sketchup::Edge).each { |e| e.hidden=true }; g
end
def paint_faces(g,m)
  g.entities.grep(Sketchup::Face).each { |f| f.material=m; f.back_material=m }
end
